import maybe, { foldMap } from 'fnts/maybe';

import mccNamesData from './mcc-names.data.json';

export type MccName = { code: string; en: string; uk: string };

// The standard merchant category code names, en and uk, shown verbatim as the sources write them.
// `mcc-names.data.json` is generated by `scripts/mcc-names/generate-mcc-names.js` from two pinned
// community files; never edit it by hand. Regenerate with the command in that script's header
// (`KIKO_REGEN_MCC=1 ... npx jest __tests__/generate-mcc-names.test.ts`), then run
// `npm run check:guard-replay`: the jest write skips the pre-write guard.
export const MCC_NAMES: readonly MccName[] = mccNamesData;

// Identical in en and uk, so a code constant and not a catalogue key.
export const MCC_NAME_SEPARATOR = ' – ';

const NAME_BY_CODE: ReadonlyMap<string, MccName> = new Map(
  MCC_NAMES.map((entry) => [entry.code, entry]),
);

export const mccNameOf = (code: string, language: string): string | undefined =>
  foldMap(maybe(NAME_BY_CODE.get(code)), (entry) => (language === 'uk' ? entry.uk : entry.en));

export const mccLabelOf = (code: string, language: string): string =>
  foldMap(maybe(mccNameOf(code, language)), (name) => `${code}${MCC_NAME_SEPARATOR}${name}`) ??
  code;
